def _fmt_hz(value):
    """Format Hz values for the status line."""
    abs_v = abs(value)
    if abs_v >= 1e9:
        return "{:.3f} GHz".format(value / 1e9)
    if abs_v >= 1e6:
        return "{:.3f} MHz".format(value / 1e6)
    if abs_v >= 1e3:
        return "{:.3f} kHz".format(value / 1e3)
    return "{:.1f} Hz".format(value)


