    def _clear_time_axis_title(self):
        """
        @brief Removes the QT GUI Time Sink bottom-axis title "Time (ms)".

        Time Sink may rewrite the X-axis title when sample-rate units update.
        Clears QwtPlot xBottom title, QwtPlotAxisXBottom, and labels containing
        "Time".
        """
        win = getattr(self, "_qtgui_time_sink_x_0_win", None)
        if win is None:
            return

        cleared = False

        # 1) Blank QwtPlot xBottom title (QwtPlot::xBottom == 2).
        for child in win.findChildren(Qt.QWidget):
            if child.metaObject().className() != "TimeDomainDisplayPlot":
                continue
            try:
                ok = Qt.QMetaObject.invokeMethod(
                    child,
                    "setAxisTitle",
                    QtCore.Qt.DirectConnection,
                    Qt.Q_ARG("int", 2),
                    Qt.Q_ARG("QString", ""),
                )
                if ok:
                    cleared = True
            except Exception:
                pass

        # 2) Clear bottom scale widget title by objectName.
        for child in win.findChildren(Qt.QWidget):
            if child.objectName() != "QwtPlotAxisXBottom":
                continue
            try:
                if hasattr(child, "setTitle"):
                    child.setTitle("")
                    cleared = True
                ok = Qt.QMetaObject.invokeMethod(
                    child,
                    "setTitle",
                    QtCore.Qt.DirectConnection,
                    Qt.Q_ARG("QString", ""),
                )
                if ok:
                    cleared = True
            except Exception:
                pass

        # 3) Hide labels whose text contains "Time" (covers "Time (ms)").
        for child in win.findChildren(Qt.QWidget):
            cname = child.metaObject().className()
            if cname not in ("QwtTextLabel", "QLabel"):
                continue
            text = ""
            try:
                if hasattr(child, "text"):
                    text = str(child.text())
            except Exception:
                text = ""
            if "time" in text.lower():
                try:
                    if hasattr(child, "setText"):
                        child.setText("")
                    child.hide()
                    cleared = True
                except Exception:
                    pass

        self._time_label_clear_tries = getattr(self, "_time_label_clear_tries", 0) + 1
        if self._time_label_clear_tries >= 15 or (
            self._time_label_clear_tries >= 5 and cleared
        ):
            timer = getattr(self, "_time_label_timer", None)
            if timer is not None:
                timer.stop()

    def _apply_stylesheet(self):
        """Load the local QSS theme for the instrument window."""
        qss_path = os.path.join(
            os.path.dirname(os.path.abspath(__file__)), "bb60c_sweep.qss")
        try:
            with open(qss_path, "r", encoding="utf-8") as f:
                self.setStyleSheet(f.read())
        except OSError as exc:
            print("Warning: failed to load stylesheet:", exc)

    def _make_group(self, title):
        box = Qt.QGroupBox(title)
        layout = Qt.QVBoxLayout(box)
        layout.setContentsMargins(8, 16, 8, 8)
        layout.setSpacing(8)
        return box

    def _make_chooser(self, label, options, labels, current, setter):
        bar = Qt.QToolBar(self)
        bar.addWidget(Qt.QLabel(label + ":"))
        combo = Qt.QComboBox()
        for text in labels:
            combo.addItem(text)
        callback = lambda i, c=combo, o=options: Qt.QMetaObject.invokeMethod(
            c, "setCurrentIndex", Qt.Q_ARG("int", o.index(i)))
        callback(current)
        combo.currentIndexChanged.connect(lambda i, o=options: setter(o[i]))
        bar.addWidget(combo)
        setattr(self, "_{0}_combo_box".format(label.lower().replace(" ", "_")), combo)
        return bar, callback

    def _schedule_apply(self):
        self._apply_timer.start()

    def _flush_device_params(self):
        """Push the latest GUI values to the block after debounce."""
        if not hasattr(self, "bb60c_bb60c_sweep_0"):
            return
        start = min(self.start_freq, self.stop_freq)
        stop = max(self.start_freq, self.stop_freq)
        if stop <= start:
            stop = start + 1e6

        self.bb60c_bb60c_sweep_0.set_start_freq(start)
        self.bb60c_bb60c_sweep_0.set_stop_freq(stop)
        self.bb60c_bb60c_sweep_0.set_ref_level(self.ref_level)
        self.bb60c_bb60c_sweep_0.set_rbw(self.rbw)
        self.bb60c_bb60c_sweep_0.set_vbw(self.vbw)
        self.bb60c_bb60c_sweep_0.set_sweep_time(self.sweep_time)
        self.bb60c_bb60c_sweep_0.set_rbw_shape(self.rbw_shape)
        self.bb60c_bb60c_sweep_0.set_rejection(self.rejection)
        self.bb60c_bb60c_sweep_0.set_detector(self.detector)
        self.bb60c_bb60c_sweep_0.set_scale(self.scale)
        self.bb60c_bb60c_sweep_0.set_units(self.units)
        self._update_status("Applied")
        # Sink may rewrite axis units/title after parameter changes.
        self._time_label_clear_tries = 0
        if hasattr(self, "_time_label_timer") and not self._time_label_timer.isActive():
            self._time_label_timer.start()
        QtCore.QTimer.singleShot(0, self._clear_time_axis_title)

    def _update_status(self, prefix="Live"):
        span = abs(self.stop_freq - self.start_freq)
        text = (
            "{prefix}  |  {start} → {stop}  |  span {span}  |  "
            "RBW {rbw}  |  ref {ref:.1f} dBm"
        ).format(
            prefix=prefix,
            start=_fmt_hz(min(self.start_freq, self.stop_freq)),
            stop=_fmt_hz(max(self.start_freq, self.stop_freq)),
            span=_fmt_hz(span),
            rbw=_fmt_hz(self.rbw),
            ref=self.ref_level,
        )
        self.status_label.setText(text)

    def closeEvent(self, event):
        self.settings = Qt.QSettings("GNU Radio", "bb60c_sweep_gui")
        self.settings.setValue("geometry", self.saveGeometry())
        self.stop()
        self.wait()
        event.accept()

